22: /**
23:  * Format tenths of a month for the runway readouts: 98 reads 9.8 months,
24:  * the no_shortfall cap reads 120+ months, and a depleted buffer reads
25:  * 0.0 months. The state wins over the number so the two special states
26:  * can never print as an ordinary figure.
27:  */
28: export function formatDeciMonths(deciMonths: number, state: RunwayState): string {
29:   if (state === 'no_shortfall') {
30:     return '120+ months'
31:   }
