  min-height: 44px;
  min-width: 44px;
  background: transparent;
  border: 1px solid var(--cp-rule);
  border-radius: var(--cp-radius);
  color: var(--cp-ink);
  font-family: var(--rp-font-utility);
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
}

.cp-chip__stepper button:hover {
  border-color: var(--rp-money);
  color: var(--rp-money);
}

/* Formula strip */

.cp-formula {
  display: grid;
  gap: 2px;
  padding: var(--rp-s3);
  background: var(--rp-verified-ghost);
  border-left: 3px solid var(--rp-verified);
  border-radius: 0 var(--cp-radius) var(--cp-radius) 0;
}

.cp-formula__line {
  margin: 0;
  font-family: var(--rp-font-utility);
  font-size: 0.8125rem;
  font-variant-numeric: tabular-nums;
  line-height: 1.6;
  color: var(--cp-ink);
  overflow-wrap: anywhere;
}

/* Actions and keyboard focus */

.cp-typed .cp-actions {
  margin-top: 0;
}

.cp-typed button:focus-visible {
  outline: 2px solid var(--rp-paper);
  outline-offset: 2px;
}

