Index: src/index.css
===================================================================
--- src/index.css
+++ src/index.css
@@ -2272,4 +2272,195 @@

 .cp-plan__block-backup .cp-plan__list li::marker {
   color: var(--rp-money);
 }
+
+/* ==========================================================================
+   Typed shock input (cp typed): the gated Gemini add on, mounted directly
+   above the preset cards in ShockPanel. Every value reuses an rp or cp
+   token; the one new custom property borrows the watch band violet so the
+   Gemini badge cannot be mistaken for a verdict band in a screenshot.
+   Motion is a single opacity pulse on the reading label, declared under
+   no preference and disabled under reduce, mirroring the cp tick above.
+   ========================================================================== */
+
+:root {
+  --cp-badge-gemini: var(--cp-band-watch);
+}
+
+.cp-typed {
+  display: grid;
+  gap: var(--rp-s3);
+  padding: var(--rp-s4);
+  background: var(--cp-inset);
+  border: 1px solid var(--cp-rule);
+  border-radius: var(--cp-radius);
+}
+
+.cp-typed__row {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  justify-content: space-between;
+  gap: var(--rp-s2) var(--rp-s3);
+}
+
+.cp-typed__input {
+  flex: 1 1 16rem;
+  min-width: 0;
+}
+
+/* Mode badge */
+
+.cp-mode-badge {
+  font-family: var(--rp-font-utility);
+  font-size: 0.6875rem;
+  font-weight: 700;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  padding: var(--rp-s1) var(--rp-s3);
+  border: 1px solid var(--cp-rule);
+  border-radius: 999px;
+  color: var(--cp-ink-dim);
+  white-space: nowrap;
+}
+
+.cp-mode-badge-gemini {
+  border-color: var(--cp-badge-gemini);
+  color: var(--cp-badge-gemini);
+}
+
+/* Reading state */
+
+.cp-reading {
+  margin: 0;
+  font-family: var(--rp-font-utility);
+  font-size: 0.75rem;
+  font-weight: 700;
+  letter-spacing: 0.16em;
+  text-transform: uppercase;
+  color: var(--rp-money);
+}
+
+@media (prefers-reduced-motion: no-preference) {
+  .cp-reading {
+    animation: cp-typed-pulse 1.6s ease-in-out infinite;
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .cp-reading {
+    animation: none;
+  }
+}
+
+@keyframes cp-typed-pulse {
+  0%,
+  100% {
+    opacity: 1;
+  }
+
+  50% {
+    opacity: 0.45;
+  }
+}
+
+/* Fallback note */
+
+.cp-note {
+  margin: 0;
+  padding: var(--rp-s2) var(--rp-s3);
+  border-left: 2px solid var(--cp-rule);
+  font-family: var(--rp-font-utility);
+  font-size: 0.8125rem;
+  line-height: 1.55;
+  color: var(--cp-ink-dim);
+}
+
+.cp-note-fallback {
+  border-left-color: var(--rp-stamp);
+  background: var(--rp-stamp-ghost);
+  color: var(--cp-ink);
+}
+
+/* Correction chips */
+
+.cp-chips {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(11rem, 1fr));
+  gap: var(--rp-s3);
+}
+
+.cp-chip {
+  display: grid;
+  align-content: start;
+  gap: var(--rp-s1);
+  min-width: 0;
+  padding: var(--rp-s3);
+  background: var(--cp-surface);
+  border: 1px solid var(--cp-rule);
+  border-radius: var(--cp-radius);
+}
+
+.cp-chip .cp-field__value {
+  font-size: 1.125rem;
+}
+
+.cp-chip .cp-hint {
+  margin: 0;
+}
+
+.cp-chip__stepper {
+  display: flex;
+  gap: var(--rp-s2);
+  margin-top: var(--rp-s1);
+}
+
+.cp-chip__stepper button {
+  min-height: 44px;
+  min-width: 44px;
+  background: transparent;
+  border: 1px solid var(--cp-rule);
+  border-radius: var(--cp-radius);
+  color: var(--cp-ink);
+  font-family: var(--rp-font-utility);
+  font-size: 1rem;
+  font-weight: 700;
+  cursor: pointer;
+}
+
+.cp-chip__stepper button:hover {
+  border-color: var(--rp-money);
+  color: var(--rp-money);
+}
+
+/* Formula strip */
+
+.cp-formula {
+  display: grid;
+  gap: 2px;
+  padding: var(--rp-s3);
+  background: var(--rp-verified-ghost);
+  border-left: 3px solid var(--rp-verified);
+  border-radius: 0 var(--cp-radius) var(--cp-radius) 0;
+}
+
+.cp-formula__line {
+  margin: 0;
+  font-family: var(--rp-font-utility);
+  font-size: 0.8125rem;
+  font-variant-numeric: tabular-nums;
+  line-height: 1.6;
+  color: var(--cp-ink);
+  overflow-wrap: anywhere;
+}
+
+/* Actions and keyboard focus */
+
+.cp-typed .cp-actions {
+  margin-top: 0;
+}
+
+.cp-typed button:focus-visible {
+  outline: 2px solid var(--rp-paper);
+  outline-offset: 2px;
+}

